"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["83535"],{3003(e){e.exports=JSON.parse('{"id":"F371","slug":"swf-permanent-income","name":"Sovereign Wealth Fund Permanent Income","subject":"Banking & Financial Institutions","section":"Other Institutions","topic":"Sovereign wealth funds","level":"Intermediate","aliases":["sovereign wealth funds","resource revenue saving","Norway 3% rule","intergenerational equity"],"formula":{"latex":"W=R\\\\,\\\\frac{1-(1+r)^{-N}}{r}+F,\\\\quad \\\\text{Permanent income}=r\\\\,W","also":[],"text":"Total wealth = present value of the remaining resource revenue (R each year for N years) + current fund; Sustainable spending (permanent income) = real return x total wealth; Amount to save each year = resource revenue - (permanent income - return on the fund)"},"symbols":[{"symbol":"R","meaning":"Annual resource revenue","unit":"money"},{"symbol":"N","meaning":"Years the resource lasts","unit":"years"},{"symbol":"r","meaning":"Expected real return","unit":"percent"},{"symbol":"F","meaning":"Current fund size","unit":"money"}],"when_to_use":"Use it to decide how much of a finite resource windfall can be spent without making future generations worse off. Treat the resource as part of wealth and spend only its return, saving the rest in a fund. This is the idea behind spending rules that cap withdrawals at an expected real return of the fund. It depends on assumptions about the price path and the real return.","worked_example":{"problem":"A state earns 30 a year from a resource that will last 25 years. It already has a fund of 100. The expected real return is 4%.","inputs":{"r":30,"n":25,"rr":4,"f":100},"steps":[{"label":"Present value of the resource revenue","working":"30 x (1-(1+0.04)^(-25)) / 0.04","value":"468.66"},{"label":"Total wealth = resource PV + fund","working":"468.662+100","value":"568.66"},{"label":"Permanent income = return x wealth","working":"0.04 x 568.662","value":"22.75"},{"label":"Return on the existing fund","working":"0.04 x 100","value":"4.00"},{"label":"Spending supported by the resource","working":"22.7465-4","value":"18.75"},{"label":"Revenue to save each year","working":"30-18.7465","value":"11.25"}],"answer":"The resource is worth 468.66 today, so total wealth is 568.66. Permanent income is 22.75, of which 4.00 comes from the fund, so the resource supports 18.75 of spending now. Of the 30 of annual revenue, 11.25 should be saved each year."},"calculator":{"available":true,"inputs":[{"id":"r","label":"Annual resource revenue","unit":"money","type":"number","default":30,"hint":""},{"id":"n","label":"Years remaining","unit":"years","type":"number","default":25,"hint":"","min":1},{"id":"rr","label":"Expected real return","unit":"%","type":"number","default":4,"hint":""},{"id":"f","label":"Current fund","unit":"money","type":"number","default":100,"hint":""}],"checks":[{"expr":"rr>0","message":"The real return must be above zero."}],"steps":[{"id":"pvr","label":"Present value of the resource revenue","expr":"r*(1-(1+rr)^(-n))/rr","format":"money"},{"id":"w","label":"Total wealth = resource PV + fund","expr":"pvr+f","format":"money"},{"id":"pi","label":"Permanent income = return x wealth","expr":"rr*w","format":"money"},{"id":"fundinc","label":"Return on the existing fund","expr":"rr*f","format":"money"},{"id":"resinc","label":"Spending supported by the resource","expr":"pi-fundinc","format":"money"},{"id":"save","label":"Revenue to save each year","expr":"r-resinc","format":"money"}],"results":["pvr","w","pi","save"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"pvr":468.662398309527,"w":568.662398309527,"pi":22.74649593238108,"fundinc":4,"resinc":18.74649593238108,"save":11.25350406761892}},"finder":{"finds":"How much of a resource windfall can be spent each year","needs":"Revenue, years, real return, current fund"},"related":[{"slug":"endowment-spending-rule","name":"Endowment Spending Rule (Yale)"},{"slug":"pv-ordinary-annuity","name":"Present Value of an Ordinary Annuity"},{"slug":"funded-ratio","name":"Funded Ratio (Liability-Driven Investing)"}],"related_ids":["F258","F019","F257"],"group":"Money, banks and the economy","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>W</mi><mo>=</mo><mi>R</mi><mtext>\u2009</mtext><mfrac><mrow><mn>1</mn><mo>\u2212</mo><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><msup><mo stretchy=\\"false\\">)</mo><mrow><mo>\u2212</mo><mi>N</mi></mrow></msup></mrow><mi>r</mi></mfrac><mo>+</mo><mi>F</mi><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Permanent\xa0income</mtext><mo>=</mo><mi>r</mi><mtext>\u2009</mtext><mi>W</mi></mrow><annotation encoding=\\"application/x-tex\\">W=R\\\\,\\\\frac{1-(1+r)^{-N}}{r}+F,\\\\quad \\\\text{Permanent income}=r\\\\,W</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"debt-restructuring-haircut","name":"Sovereign Debt Restructuring: NPV Haircut"},"next":{"slug":"srisk","name":"SRISK (Systemic Risk Contribution)"},"lesson":null,"total":522}')}}]);